def observation(model, data):
    """Builds the basic observation of the physics state (the logger and the policies read it).

    It has the same keys as RobotSimulator.get_observation() in src/simulator.py, except the entries for tracked bodies.

    Args:
        model (mujoco.MjModel): The compiled MuJoCo model. Not used; it is accepted so the call matches the simulator's.
        data (mujoco.MjData): Simulation state to copy from.

    Returns:
        dict: The observation, with the keys
            "time": simulation time in seconds.
            "joint_angles": copy of `data.qpos`, joint positions (radians, or metres for slide joints; the free joint holds position and quaternion).
            "joint_velocities": copy of `data.qvel`, joint velocities (radians or metres per second).
            "joint_torques": copy of `data.actuator_force`, the force each actuator actually applied (newton metres for rotary joints, newtons
            for slides and the pedestal lift).
            "ctrl": copy of `data.ctrl`, what was commanded (target angles or heights for position actuators, wheel torque commands for the motors).
    """
    return {
        "time": data.time,
        "joint_angles": data.qpos.copy(),
        "joint_velocities": data.qvel.copy(),
        # actual actuator force (N m for rotary joints, N for slides and the pedestal lift), as
        # the servo applied it; "ctrl" is what was commanded (target angles/heights for position
        # actuators, wheel torque commands for the motors)
        "joint_torques": data.actuator_force.copy(),
        "ctrl": data.ctrl.copy(),
    }


def _headless_context(model):
    """Creates an offscreen OpenGL context for rendering without a window.

    Args:
        model (mujoco.MjModel): The compiled MuJoCo model. The context size is its offscreen buffer size
            (`model.vis.global_.offwidth` by `offheight`).

    Returns:
        tuple: (gl, context), where gl (mujoco.GLContext) is made current and must be kept alive and freed by the caller, and context
        (mujoco.MjrContext) is the MuJoCo rendering context to hand to the camera rigs.
    """
    gl = mujoco.GLContext(model.vis.global_.offwidth, model.vis.global_.offheight)
    gl.make_current()
    return gl, mujoco.MjrContext(model, mujoco.mjtFontScale.mjFONTSCALE_150)


def _filter_by_route(cmd, name, routes):
    """Keeps only the part of a command that a source owns according to the router.

    The loop calls it for base, pedestal, arms and idle commands.

    Args:
        cmd (dict): A command with a "mode" key (not "request_teleop"; see src/commands.py for the format).
        name (str): Name of the source that produced the command.
        routes (dict): Router table mapping each field ("base", "pedestal", "arms.left", "arms.right", "gripper.left", "gripper.right")
            to a source name or a tuple of source names.

    Returns:
        dict or None: `cmd` itself for an idle command, or for a base or pedestal command whose field the source owns; for an arms
        command a new dict with only the arm_targets and gripper entries of the sides the source owns; None if the source owns nothing
        of the command.
    """
    mode = cmd["mode"]
    owns = lambda field: name in ((routes.get(field),) if not isinstance(routes.get(field), tuple) else routes[field])
    if mode == "idle":
        return cmd
    if mode in ("base", "pedestal"):
        return cmd if owns(mode) else None
    at = {sd: q for sd, q in cmd.get("arm_targets", {}).items() if owns(f"arms.{sd}")}
    gr = {sd: g for sd, g in cmd.get("gripper", {}).items() if owns(f"gripper.{sd}")}
    if not at and not gr:
        return None
    out = {"mode": "arms"}
    if at:
        out["arm_targets"] = at
    if gr:
        out["gripper"] = gr
    return out


def run_loop(model, data, sources, cfg, viewer=None, logger=None):
    """Runs the simulation: settles the robot, then loops over ticks until a stop condition, then cleans up.

    Each tick builds the observation, steps every source, validates and applies their commands, advances the physics by one tick and updates
    the viewer. The module docstring describes the tick, the router, the controller modes, exclusivity and the supervisor hook in full.
    An exception raised inside the tick loop is printed with its traceback and ends the loop; the cleanup still runs and the result is returned.

    The observation `obs` that sources and the "on_tick" hook receive holds the keys of `observation()` and also:
    "tick" (int, tick number), "timestep" (float, physics step in seconds), "steps_per_frame" (int, physics steps per tick),
    "base_pose" ((x, y, yaw) of the base in metres and radians), "pedestal_height" (float, metres), "applied" (dict of the loop's current
    targets: "twist", "gripper_force", "pedestal", "arm_targets", "gripper", "mode"), "cameras" (dict of camera
    name to image, or None without policy cameras), "render" (the hook API's render(camera_name): one frame of a camera from the current state, on demand; a source that needs an image at one tick, such as a completion check, calls it), "mode" ("teleop" or "auto"), "operator" ({"requested", "responded"}), and "policy"
    (the auto source's status(), only if it has one).

    Args:
        model (mujoco.MjModel): The compiled MuJoCo model, with the arm, finger and pedestal position actuators and the wheel motors.
            Its finger actuators' force range is rewritten by the loop (gripper force limit).
        data (mujoco.MjData): Simulation state. It is modified: the base is spawned and settled, then stepped.
        sources (dict): Maps a source name to a source dict. A source dict has the callable "step" (obs -> a command dict, a list of them, or
            None) and may have "start" (called once after the settle), "cleanup" (called at the end, unless "started" is present and false),
            "name" (used in messages), "hz" (the rate of its commands: a number, or a callable returning it; default the tick rate, see
            the module docstring's target modes), "state" (the keyboard source's `["state"]["drive"]` and the teleop source's `["state"]["preview_frame"]` are
            read for the viewer), and for the teleop source "status", "enable" and "disable" callables, and for the auto source "status" and
            "resume" callables.
        cfg (dict): Settings that override the defaults in LOOP_CFG. See the comments there for each key.
        viewer (dict or None): The window, as built by `make_glfw_viewer` in src/glfw_viewer.py. The loop uses the keys "key_down",
            "context", "frame" (called once per tick with an info dict), "finish", "close" and "timers". Defaults to None (headless run).
        logger (object or None): Trajectory logger with `record(obs)`, a `trajectory` list and `save()`. It records only while logging is
            switched on with the toggle_log hotkey. Defaults to None.

    Returns:
        dict: Summary of the run, with the keys
            "frames": number of ticks run (int).
            "hold_log": list of dicts, one per completed exclusivity hold, each with "t_start", "t_end", "duration" (seconds),
            "waiting" (mode of the held command), "blocked_by" (the active subsystem it waited for) and "applied" (True).
            "routes": the router table at the end of the run (dict of field to source name or tuple of names).
            "stopped_by": reason given to loop["stop"] by the hook or "aborted_by_operator", or None if the run ended otherwise (window
            closed, Esc, benchmark frames reached, replay finished).
            "bridge_log": list of the command bridge's rejections and suspensions (empty if the bridge is off), each {"tick", "time", "status", "kind", "side", "joint", "value", "limit"}.
            "mode_log": list of mode switch records, each {"tick", "time", "from", "to", "cause", "reason", "stage"}.

    Raises:
        ValueError: If the physics rate is not a whole multiple of the camera rate or of cfg["source_hz"], if cfg["mode"] is not "teleop"
            or "auto", if cfg["target_mode"] is not "interpolate" or "hold", or if cfg["auto_source"] is not one of the sources.
        RuntimeError: If an actuator the loop needs (the wheel motors, the arm, finger and pedestal actuators) is not in the model.
    """
    cfg = {**LOOP_CFG, **cfg}
    routes = {**DEFAULT_ROUTES, **cfg["routes"]}
    held = cfg["held"] or (viewer["key_down"] if viewer else (lambda code: False))
    hk = cfg["hotkeys"]
    tick_ref = cfg["tick_ref"]
    pc = time.perf_counter

    # --- Multi-rate schedule (all derived from the model timestep) ---
    physics_hz = 1.0 / model.opt.timestep

    def _every(hz, what):
        """Converts a rate to a number of physics steps.

        Args:
            hz (float): Rate in hertz. The physics rate (`physics_hz` of the enclosing function) must be a whole multiple of it.
            what (str): Name of the rate, used in the error message.

        Returns:
            int: Number of physics steps per period of `hz`.

        Raises:
            ValueError: If the physics rate is not an integer multiple of `hz`.
        """
        n = physics_hz / hz
        if abs(n - round(n)) > 1e-6:
            raise ValueError(f"physics {physics_hz:.1f} Hz is not an integer "
                             f"multiple of {what} {hz} Hz")
        return int(round(n))

    camera_hz = cfg["camera_hz"] or robot_specs.CAMERA_HZ
    cam_every = _every(camera_hz, "camera")
    steps_per_frame = _every(cfg["source_hz"], "source")
    tick_dt = steps_per_frame * model.opt.timestep
    if cfg["target_mode"] not in ("interpolate", "hold"):
        raise ValueError(f"cfg['target_mode'] must be 'interpolate' or 'hold', not {cfg['target_mode']!r}")
    interpolate = cfg["target_mode"] == "interpolate"
    warmup_steps = round(cfg["warmup_s"] * physics_hz)
    resettle_steps = round(cfg["resettle_s"] * physics_hz)
    print(f"Rates: physics {physics_hz:.0f} Hz (arm/finger servos every step) | cameras every {cam_every} steps "
          f"({physics_hz / cam_every:.0f} Hz, "
          f"{'one camera per tick' if cfg['camera_roundrobin'] else 'all cameras per tick'}) "
          f"| commands/viewer {steps_per_frame} steps/frame "
          f"(~{physics_hz / steps_per_frame:.0f} Hz)")
    print("  routes: " + ", ".join(f"{k}->{v}" for k, v in routes.items()))

    # --- Actuators ---
    def aid(name):
        """Looks up an actuator by name.

        Args:
            name (str): Actuator name in the model.

        Returns:
            int: The actuator's index.

        Raises:
            RuntimeError: If the model has no actuator of that name.
        """
        a = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, name)
        if a < 0:
            raise RuntimeError(f"Actuator '{name}' not in model.")
        return a

    wheel_ids = [aid("left_motor"), aid("right_motor")]
    claimed = set(wheel_ids) | set(cfg["claimed_ids"])
    # Unclaimed actuators hold their settled position so the robot
    # doesn't collapse.  This is not "auto" — it's just gravity
    # compensation for joints nobody is actively controlling.
    unclaimed_ids = sorted(set(range(model.nu)) - claimed)

    base_dof = find_base_dof(model)
    if base_dof is not None:
        print(f"  Free joint '{model.joint(int(model.dof_jntid[base_dof])).name}' "
              f"dof_adr={base_dof} (velocity drive target)")
    else:
        print("  WARNING: no free joint found — velocity drive disabled")

    # Arms, fingers and the pedestal lift are MuJoCo position actuators (ctrl = target
    # angle / height); only the wheel motors are torque actuators and they get ctrl 0 (the base is
    # velocity-driven). A masked-out position actuator therefore holds its last hold target, since
    # ctrl 0 would mean "go to angle 0", not "limp".
    is_pos = model.actuator_biastype == mujoco.mjtBias.mjBIAS_AFFINE

    sides = ("left", "right")
    arm_act = {s: [aid(f"{s}_joint{i}_ctrl") for i in range(1, 8)] for s in sides}
    fing_act = {s: [aid(f"{s}_gripper_ctrl")] for s in sides}      # one actuator per hand: it drives both fingers (finger 2 follows finger 1)
    jr = lambda a: model.jnt_range[model.actuator_trnid[a, 0]]
    vadr = lambda a: int(model.jnt_dofadr[model.actuator_trnid[a, 0]])
    arm_vadr = {s: [vadr(a) for a in arm_act[s]] for s in sides}
    fing_vadr = [vadr(a) for s in sides for a in fing_act[s]]
    from src.gravity_ff import ArmGravityFeedforward
    gff = ArmGravityFeedforward(model, arm_act, fing_act, sides)          # M185: the arm's gravity torque as a feedforward on the targets
    ped_aid = aid(robot_specs.PEDESTAL_SPECS["actuator_name"])
    ped_lo, ped_hi = model.actuator_ctrlrange[ped_aid]
    ped_vadr = vadr(ped_aid)
    ped_qadr = int(model.jnt_qposadr[model.actuator_trnid[ped_aid, 0]])
    limits = {"gripper_force_ceiling": float(robot_specs.ARM_ACTUATOR_SPECS["fingers"]["force_limit"]), "arm": {s: (np.array([jr(a)[0] for a in arm_act[s]]), np.array([jr(a)[1] for a in arm_act[s]])) for s in sides},
              "gripper": tuple(jr(fing_act["left"][0])), "pedestal": (float(ped_lo), float(ped_hi))}

    base_body_id = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "base_link")
    if base_body_id < 0:
        base_body_id = 1

    # --- Spawn and settle ---
    if cfg["spawn_pos"] is not None:
        data.qpos[0:3] = cfg["spawn_pos"]
        if cfg["spawn_yaw"] is not None:
            data.qpos[3:7] = [math.cos(cfg["spawn_yaw"] / 2), 0.0, 0.0, math.sin(cfg["spawn_yaw"] / 2)]
        mujoco.mj_forward(model, data)

    print("Settling physics ...")
    # Hold the unclaimed position actuators at home (zero; the pedestal at its default target) during warmup so the joints settle under
    # proportional-derivative (PD) control instead of drooping limp and then oscillating when the
    # main loop starts.
    hold_qpos_targets = np.zeros(model.nu)
    hold_qpos_targets[ped_aid] = robot_specs.PEDESTAL_SPECS["target_height"]
    for i in range(warmup_steps):
        # Only apply hold targets for unclaimed position actuators; zero the rest
        for a in range(model.nu):
            data.ctrl[a] = hold_qpos_targets[a] if (a in unclaimed_ids and is_pos[a]) else 0.0
        gff.apply(data.ctrl, data)
        mujoco.mj_step(model, data)
    print(f"Settled at z={data.qpos[2]:.4f}")

    # Capture the natural resting pose after warmup — arms hanging down
    # under gravity.  Zero velocities so they're still, then re-settle
    # briefly with proportional-derivative (PD) holding at this pose.  The PD doesn't need to fight
    # gravity (it's already at equilibrium) — it just resists disturbances
    # when the base moves.
    hold_qpos_targets = np.zeros(model.nu)
    for a in unclaimed_ids:
        qadr = model.jnt_qposadr[model.actuator_trnid[a, 0]]
        hold_qpos_targets[a] = data.qpos[qadr]  # actual drooped angle
        if model.actuator_ctrllimited[a]:       # the settled angle can sit a hair outside a soft joint limit (e.g. -3e-5 rad on a joint whose limit is 0 at the lower real gains); a
            hold_qpos_targets[a] = np.clip(hold_qpos_targets[a], *model.actuator_ctrlrange[a])   # target outside the range would be clipped later and look like an unapplied command
        va = model.jnt_dofadr[model.actuator_trnid[a, 0]]
        data.qvel[va] = 0.0  # kill any residual swing
    hold_qpos_targets[ped_aid] = robot_specs.PEDESTAL_SPECS["target_height"]
    mujoco.mj_forward(model, data)

    # Brief re-settle with PD active so everything stabilizes
    for i in range(resettle_steps):
        for a in unclaimed_ids:
            if is_pos[a]:
                data.ctrl[a] = hold_qpos_targets[a]
        gff.apply(data.ctrl, data)
        mujoco.mj_step(model, data)
    print(f"Arms locked at resting pose, re-settled at z={data.qpos[2]:.4f}")

    # Arm and finger targets in "interpolate" mode: the ctrl of actuator a at physics step k of its ramp is ramp_from + (target - ramp_from) * k / ramp_len
    # (the target itself once k >= ramp_len). A command for the actuator starts a new ramp from the ctrl of the last physics step (`last_ctrl`).
    # Actuators without a ramp (the pedestal, the wheel motors) have ramp_k huge, so their ctrl is the target.
    last_ctrl = np.where(is_pos, hold_qpos_targets, 0.0)
    ramp_from, ramp_len, ramp_k = last_ctrl.copy(), np.ones(model.nu), np.full(model.nu, 1e12)
    steps_axis = np.arange(1, steps_per_frame + 1, dtype=float)[:, None]

    def ctrl_block():
        """Computes the ctrl vector of each physics step of the coming tick and moves the ramps on by one tick.

        Reads `hold_qpos_targets` and the ramp state of the enclosing function; sets `last_ctrl` to the last row. Wheel motors get 0.

        Returns:
            numpy.ndarray: Shape (steps_per_frame, model.nu).
        """
        nonlocal last_ctrl
        frac = np.clip((ramp_k[None, :] + steps_axis) / ramp_len[None, :], 0.0, 1.0)
        block = np.where(frac >= 1.0, hold_qpos_targets[None, :], ramp_from[None, :] + (hold_qpos_targets - ramp_from)[None, :] * frac)
        block = np.where(is_pos[None, :], block, 0.0)
        ramp_k[:] += steps_per_frame
        last_ctrl = block[-1].copy()
        return block

    def command_steps(src):
        """Returns the command period of a source in physics steps: from its "hz" (a number or a callable), at least one tick."""
        hz = src.get("hz")
        hz = hz() if callable(hz) else hz
        return steps_per_frame if not hz else max(steps_per_frame, int(round(physics_hz / hz)))

    replay = cfg["replay"]
    recorder = None
    if replay is not None:
        replay["on_start"](model, data)
    elif cfg["record_run"]:
        recorder = RunRecorder(cfg["record_run"], model, data, {**cfg, "claimed_ids": list(cfg["claimed_ids"])}, cfg["record_meta"],
                               cfg["source_hz"], steps_per_frame)

    # Sources that build things that need the settled robot (the teleop session, the fake operator's clock)
    for src in sources.values():
        if "start" in src:
            src["start"]()

    # --- Cameras: the viewer's GL context, or an offscreen one when headless ---
    rig, gl_keepalive = None, None
    if cfg["cameras"]:
        if viewer is not None:
            context = viewer["context"]
        else:
            gl_keepalive, context = _headless_context(model)
        # Render once so frames exist before the first camera tick.
        rig = CameraRig(model, robot_specs.CAMERA_SPECS, context, shadows=cfg["camera_shadows"])
        rig.render(data)
    cam_names = [cs["name"] for cs in robot_specs.CAMERA_SPECS]
    cam_tick = 0

    # --- Operator insets: their own rig (shadows off, small), rendered only on viewer redraws ---
    draw_every = max(1, round(cfg["source_hz"] / cfg["viewer_draw_hz"])) if viewer is not None else 1
    irig, inset_every, inset_tick = None, 1, 0
    if viewer is not None and cfg["inset_cameras"]:
        w_i, h_i = cfg["inset_res"]
        ispecs = [{**cs, "resolution": (w_i, h_i), "shadows": cfg["inset_shadows"]} for cs in robot_specs.CAMERA_SPECS]
        irig = CameraRig(model, ispecs, viewer["context"], shadows=cfg["inset_shadows"])
        irig.render(data)
        # renders per second = n_cameras * inset_hz, one every `inset_every` redraws
        inset_every = max(1, round((cfg["source_hz"] / draw_every) / (len(ispecs) * cfg["inset_hz"])))
        print(f"Viewer: redraw every {draw_every} ticks ({cfg['source_hz'] / draw_every:.1f} Hz); operator insets {w_i}x{h_i}, shadows "
              f"{'on' if cfg['inset_shadows'] else 'off'}, one camera every {inset_every} redraws "
              f"(each camera ~{cfg['source_hz'] / draw_every / inset_every / len(ispecs):.1f} Hz)")
    elif viewer is not None:
        print(f"Viewer: redraw every {draw_every} ticks ({cfg['source_hz'] / draw_every:.1f} Hz); no operator insets")

    # --- The loop's state: the applied targets, the base Twist, the exclusivity / hold bookkeeping ---
    st = {"twist": (0.0, 0.0)}
    ex = {"active": None, "pending": None, "hold_t0": None, "hold_blocker": None, "log": [], "warned": set(),
          "still": {"base": 0.0, "pedestal": 0.0, "arms": 0.0}}
    msgs_seen = set()

    # Gripper force limits: the force each finger of a gripper may apply (N). Set by a gripper command's max_force (default: the hardware ceiling) and
    # written into the finger actuators' force range, once per tick, here and only here (policies never touch the model). The model is shared by
    # episodes, so every run starts by putting the ceiling back.
    ceiling = limits["gripper_force_ceiling"]
    fingers_per_act = robot_specs.ARM_ACTUATOR_SPECS["fingers"]["fingers_per_actuator"]
    grip_force = {s: ceiling for s in sides}
    grip_set = {s: None for s in sides}

    def set_grip_force(forces):
        """Writes the finger force limits into the model's finger actuators.

        Changes `model.actuator_forcerange` of the gripper actuator of a side to [-n F, n F] (the one actuator drives both fingers, n = fingers_per_actuator, so each finger
        may press with F), only when F differs from the value written last time (kept in `grip_set` of the enclosing function).

        Args:
            forces (sequence of float): Force limit in newtons for each finger, one value for the left gripper and one for the right,
                in that order.
        """
        for s, F in zip(sides, forces):
            if grip_set[s] != F:
                model.actuator_forcerange[fing_act[s]] = [-fingers_per_act * F, fingers_per_act * F]
                grip_set[s] = F

    set_grip_force([ceiling, ceiling])

    def applied():
        """Reports the targets the loop is currently applying (the "applied" entry of the observation).

        Reads the base Twist, the gripper force limits, the hold targets from the enclosing function.

        Returns:
            dict: With the keys
                "twist": (forward speed in metres per second, yaw rate in radians per second).
                "gripper_force": {side: force limit per finger in newtons}.
                "pedestal": pedestal lift target in metres.
                "arm_targets": {side: list of 7 joint targets in radians}.
                "gripper": {side: finger travel target in metres}.
                "mode": the active subsystem under exclusivity (a name or None).
        """
        return {"twist": st["twist"], "gripper_force": dict(grip_force), "pedestal": float(hold_qpos_targets[ped_aid]),
                "arm_targets": {s: [float(hold_qpos_targets[a]) for a in arm_act[s]] for s in sides},
                "gripper": {s: float(hold_qpos_targets[fing_act[s][0]]) for s in sides}, "mode": ex["active"]}

    def apply_cmd(cmd):
        """Stores a validated command in the loop's targets (nothing is moved yet).

        An arms command also starts, in "interpolate" mode, the ramp of every actuator it sets (over cmd["period_steps"], one tick if absent).
        A base command sets the Twist `st["twist"]`; a pedestal command sets the pedestal entry of `hold_qpos_targets`; an arms command sets the arm and finger entries of
        `hold_qpos_targets` and the gripper force limits `grip_force` (None means the ceiling). Other modes change nothing.

        Args:
            cmd (dict): A command returned by `validate_command` (clean, with "mode").
        """
        mode = cmd["mode"]
        if mode == "base":
            st["twist"] = cmd["twist"]
        elif mode == "pedestal":
            hold_qpos_targets[ped_aid] = cmd["height"]
        elif mode == "arms":
            moved = []
            for s, q in cmd.get("arm_targets", {}).items():
                hold_qpos_targets[arm_act[s]] = q
                moved += arm_act[s]
            for s, g in cmd.get("gripper", {}).items():
                hold_qpos_targets[fing_act[s]] = g
                moved += fing_act[s]
            if interpolate and moved:                       # a new ramp from where the ctrl is now to the new target
                ramp_from[moved], ramp_k[moved], ramp_len[moved] = last_ctrl[moved], 0.0, cmd.get("period_steps", steps_per_frame)
            for s, F in cmd.get("gripper_force", {}).items():
                grip_force[s] = ceiling if F is None else F

    # --- The command bridge (row M193): the real arms' command limits between the sources and the arm targets ---
    bcfg = {**COMMAND_BRIDGE_CFG, **(cfg.get("command_bridge") or {})}
    bridge = {"on": bool(bcfg["enabled"]) and cfg["replay"] is None, "cmd": None, "target": {}, "accepted": {}, "suspended": False, "log": [], "printed": 0}
    bridge_every = max(1, int(round(cfg["source_hz"] / bcfg["rate_hz"])))
    bridge_step = bcfg["max_joint_velocity_rad_s"] / bcfg["rate_hz"]                      # rad: the most the command moves per update
    arm_qadr = {s: [int(model.jnt_qposadr[model.actuator_trnid[a, 0]]) for a in arm_act[s]] for s in sides}

    def bridge_note(frame_, side, joint, kind, value, limit):
        """Logs a bridge rejection or suspension (the joint's number is 1 to 7) and prints the first 20."""
        rec_ = {"tick": frame_, "time": float(data.time), "status": status, "kind": kind, "side": side, "joint": joint, "value": float(value), "limit": float(limit)}
        bridge["log"].append(rec_)
        if bridge["printed"] < 20:
            bridge["printed"] += 1
            print(f"[bridge] t={rec_['time']:.2f} s ({status}): {kind}: {side} joint {joint}, value {value:+.3f}, limit {limit:+.3f}")

    def bridge_precheck(cmd, frame_):
        """Takes an arms command's targets that lie outside the joint limits out of it (the whole arm targets are rejected and logged). Returns the command, or None if nothing is left.

        Runs on the raw command, before validate_command clips out-of-range values.
        """
        if not bridge["on"] or not isinstance(cmd, dict) or cmd.get("mode") != "arms" or not isinstance(cmd.get("arm_targets"), dict):
            return cmd
        for s, q in cmd["arm_targets"].items():
            lo, hi = limits["arm"][s]
            q = np.asarray(q, float)
            bad = np.nonzero((q < lo) | (q > hi))[0] if q.shape == lo.shape else []
            if len(bad):
                k = int(bad[0])
                bridge_note(frame_, s, k + 1, "rejected: target outside the joint limits", q[k], lo[k] if q[k] < lo[k] else hi[k])
                rest = {kk: v for kk, v in cmd.items() if kk != "arm_targets"}
                return rest if any(kk in rest for kk in ("gripper", "gripper_force")) else None
        return cmd

    def bridge_take(cmd):
        """Keeps the arm targets of an arms command as the bridge's latest targets and returns the command without them (None if nothing else is in it)."""
        if not bridge["on"] or cmd["mode"] != "arms" or not cmd.get("arm_targets"):
            return cmd
        for s, q in cmd["arm_targets"].items():
            bridge["target"][s] = np.array(q, float)
        rest = {kk: v for kk, v in cmd.items() if kk != "arm_targets"}
        return rest if any(kk in rest for kk in ("gripper", "gripper_force")) else None

    def bridge_update(frame_):
        """One update of the bridge (every `bridge_every` ticks): suspension check, rejection check, then the limited command is applied (ramped over the update period)."""
        if not bridge["on"] or not bridge["target"] or frame_ % bridge_every:
            return
        if bridge["cmd"] is None:
            bridge["cmd"] = {s: hold_qpos_targets[arm_act[s]].copy() for s in sides}
        cmd_q = bridge["cmd"]
        err = {s: cmd_q[s] - data.qpos[arm_qadr[s]] for s in sides}                      # the command's distance from the measured joint angles
        worst = max(((float(np.max(np.abs(err[s]))), s) for s in sides))
        if worst[0] > bcfg["max_tracking_error_rad"]:
            if not bridge["suspended"]:
                bridge["suspended"] = True
                k = int(np.argmax(np.abs(err[worst[1]])))
                bridge_note(frame_, worst[1], k + 1, "suspended: tracking error", err[worst[1]][k], bcfg["max_tracking_error_rad"])
            return
        if bridge["suspended"]:
            bridge["suspended"] = False
            bridge_note(frame_, worst[1], 0, "resumed: tracking error recovered", worst[0], bcfg["max_tracking_error_rad"])
        out = {}
        for s, tgt in bridge["target"].items():
            d_ = tgt - cmd_q[s]
            if float(np.max(np.abs(d_))) > bcfg["max_target_step_rad"]:
                k = int(np.argmax(np.abs(d_)))
                bridge_note(frame_, s, k + 1, "rejected: target step too large", d_[k], bcfg["max_target_step_rad"])
                tgt = bridge["accepted"].get(s, cmd_q[s])                                      # the previous accepted target stays
                d_ = tgt - cmd_q[s]
            else:
                bridge["accepted"][s] = tgt.copy()
            cmd_q[s] = cmd_q[s] + np.clip(d_, -bridge_step, bridge_step)
            out[s] = [float(v) for v in cmd_q[s]]
        apply_cmd({"mode": "arms", "arm_targets": out, "period_steps": bridge_every * steps_per_frame})

    # --- Exclusivity and the hold rule ---
    def measure_still():
        """Updates, per subsystem, how long its measured velocity has been below the settled threshold.

        Reads the measured velocities from `data.qvel` and the thresholds from `cfg` ("settle_*"). For the base the commanded Twist must be
        below the thresholds too. For each of "base", "pedestal" and "arms" the matching entry of `ex["still"]` grows by one tick
        (`tick_dt` seconds) while the subsystem is below its thresholds and is reset to 0 otherwise.
        """
        qv = data.qvel
        base_ok = base_dof is None or (math.hypot(qv[base_dof], qv[base_dof + 1]) < cfg["settle_base_lin"]
                                       and abs(qv[base_dof + 5]) < cfg["settle_base_ang"]
                                       and abs(st["twist"][0]) < cfg["settle_base_lin"] and abs(st["twist"][1]) < cfg["settle_base_ang"])
        ped_ok = abs(qv[ped_vadr]) < cfg["settle_ped_speed"]
        arm_ok = max(abs(qv[v]) for s in sides for v in arm_vadr[s]) < cfg["settle_arm_speed"] \
            and max(abs(qv[v]) for v in fing_vadr) < cfg["settle_finger_speed"]
        for name, ok in (("base", base_ok), ("pedestal", ped_ok), ("arms", arm_ok)):
            ex["still"][name] = ex["still"][name] + tick_dt if ok else 0.0

    dwell = {"base": cfg["settle_base_dwell"], "pedestal": cfg["settle_ped_dwell"], "arms": cfg["settle_arm_dwell"]}
    settled = lambda sub: ex["still"][sub] >= dwell[sub]

    def stop_base():
        """Brings the Twist toward zero by one tick at the configured deceleration (during a hold, after a mode switch, or on idle).

        Changes `st["twist"]` by at most cfg["base_stop_lin_decel"] and cfg["base_stop_ang_decel"] times the tick length, without
        crossing zero.
        """
        lin, ang = st["twist"]
        dl, da = cfg["base_stop_lin_decel"] * tick_dt, cfg["base_stop_ang_decel"] * tick_dt
        st["twist"] = (lin - math.copysign(min(abs(lin), dl), lin), ang - math.copysign(min(abs(ang), da), ang))

    def exclusive_select(cmds, t):
        """Reduces this tick's commands to the ones to apply now, at most one subsystem (the exclusivity and hold rule).

        If several non-idle commands arrive only the first is used (warned once per combination of modes). An idle command with nothing else
        clears any waiting command and brings the base to a stop. A command for the active subsystem, or for any subsystem once the active
        one has settled, is applied (a finished hold is logged in `ex["log"]` and printed). Otherwise it waits in `ex["pending"]`, replacing any older
        waiting command, and a moving base is brought to a stop meanwhile.

        Args:
            cmds (list of dict): This tick's validated commands.
            t (float): Simulation time in seconds.

        Returns:
            list of dict: The commands to apply now: empty or one command. Changes `ex`, and `st["twist"]` through `stop_base`.
        """
        nonidle = [c for c in cmds if c["mode"] != "idle"]
        modes = {c["mode"] for c in nonidle}
        if len(modes) > 1 and tuple(sorted(modes)) not in ex["warned"]:
            ex["warned"].add(tuple(sorted(modes)))
            print(f"[exclusive] commands for {sorted(modes)} in one tick: only the first ('{nonidle[0]['mode']}') is used")
        new = nonidle[0] if nonidle else None
        if new is None and any(c["mode"] == "idle" for c in cmds):
            ex["pending"] = None
            stop_base()
            return []
        cand = new if new is not None else ex["pending"]
        if cand is None:
            return []
        active = ex["active"]
        if active in (None, cand["mode"]) or settled(active):
            if ex["pending"] is not None or ex["hold_t0"] is not None:
                dur = t - ex["hold_t0"]
                ex["log"].append({"t_start": ex["hold_t0"], "t_end": t, "duration": dur, "waiting": cand["mode"],
                                  "blocked_by": ex["hold_blocker"], "applied": True})
                print(f"[hold] t={t:.2f} s: '{cand['mode']}' command applied after waiting {dur:.2f} s for '{ex['hold_blocker']}' to settle")
            ex["pending"], ex["hold_t0"], ex["hold_blocker"] = None, None, None
            ex["active"] = cand["mode"]
            return [cand]
        if ex["hold_t0"] is None:
            ex["hold_t0"], ex["hold_blocker"] = t, active
            print(f"[hold] t={t:.2f} s: '{cand['mode']}' command waits for '{active}' to settle")
        ex["pending"] = cand                       # newest replaces older
        if active == "base":
            stop_base()
        return []

    # --- Controller mode: "teleop" (the router as configured) or "auto" (the auto source owns every field) ---
    auto_src = cfg["auto_source"]
    if cfg["mode"] not in ("teleop", "auto"):
        raise ValueError(f"cfg['mode'] must be 'teleop' or 'auto', not {cfg['mode']!r}")
    if (cfg["mode"] == "auto" or auto_src is not None) and auto_src not in sources:
        raise ValueError(f"cfg['auto_source'] = {auto_src!r} is not one of the sources {sorted(sources)}")
    ctl = {"mode": "teleop", "note": None, "ramp": False, "log": [], "tables": {"teleop": dict(routes)},
           "requested": False, "responded": False, "alert_seq": 0}
    teleop = sources.get("teleop")

    def switch_mode(new, cause, reason=None):
        """Switches the controller between "teleop" and "auto" mode.

        Does nothing if the mode is already `new`. Otherwise it saves the operator's routing table when leaving teleop (and disables the teleop
        source if it owns the arms), replaces the router table in place (all fields to the auto source, or the saved teleop table, enabling the
        teleop source again if it owned the arms), sets the base-stop ramp, clears the exclusivity state, updates the operator-request flags and
        alert counter in `ctl`, appends a record to `ctl["log"]` (using the enclosing `frame` tick counter) and prints the switch.

        Args:
            new (str): The mode to switch to, "teleop" or "auto".
            cause (str): Why: "operator_key", "policy_request" or "initial".
            reason (str or None): Text given by the policy with a request, shown to the operator. Defaults to None.

        Raises:
            ValueError: If `new` is "auto" and the loop has no auto source.
        """
        old = ctl["mode"]
        if new == old:
            return
        if new == "auto" and auto_src is None:
            raise ValueError("no auto source: the loop has no auto mode")
        if old == "teleop":                               # keep the operator's arm routing (F2) for the way back
            ctl["tables"]["teleop"] = dict(routes)
            if teleop is not None and routes["arms.left"] == "teleop":
                teleop["disable"]()
        routes.clear()
        routes.update(ctl["tables"]["teleop"] if new == "teleop" else {k: auto_src for k in ROUTE_KEYS})
        if new == "teleop" and teleop is not None and routes["arms.left"] == "teleop":
            teleop["enable"]()
        ctl.update(mode=new, ramp=True, note=reason if cause == "policy_request" else None, requested=cause == "policy_request", responded=False)
        if cause == "policy_request":
            ctl["alert_seq"] += 1
        ex.update(active=None, pending=None, hold_t0=None, hold_blocker=None)
        stage = None
        if auto_src is not None and "status" in sources[auto_src]:
            stage = sources[auto_src]["status"]().get("stage")
        ctl["log"].append({"tick": frame, "time": data.time, "from": old, "to": new, "cause": cause, "reason": reason, "stage": stage})
        print(f"[mode] t={data.time:.2f} s (tick {frame}): {old.upper()} -> {new.upper()}  ({cause}{': ' + reason if reason else ''})"
              + (f"  [stage {stage}]" if stage else ""))

    def key_down(spec):
        """Tells whether a hotkey is currently held down.

        Args:
            spec (int or tuple or list): One key code or several (for example Enter and the keypad Enter).

        Returns:
            bool: True if any of the keys is held, according to the `held` function of the enclosing function.
        """
        return any(held(c) for c in (spec if isinstance(spec, (tuple, list)) else (spec,)))

    def key_label(spec):
        """Gives a readable name for a hotkey, for the banner text.

        Args:
            spec (int or tuple or list): One key code, or several, of which the first is named.

        Returns:
            str: The name of the matching `glfw.KEY_*` constant without the prefix, in title case ("Delete"), or the key code as text if
            no constant matches.
        """
        import glfw
        code = spec[0] if isinstance(spec, (tuple, list)) else spec
        for n in dir(glfw):
            if n.startswith("KEY_") and getattr(glfw, n) == code:
                return n[4:].replace("_", " ").title()
        return str(code)

    all_keys = None

    def any_key_down():
        """Tells whether any keyboard key at all is held down (used to see that the operator has responded).

        Builds the list of all `glfw.KEY_*` codes on first use and keeps it in `all_keys` of the enclosing function.

        Returns:
            bool: True if any key is held, according to the `held` function of the enclosing function.
        """
        nonlocal all_keys
        if all_keys is None:
            import glfw
            all_keys = [getattr(glfw, n) for n in dir(glfw) if n.startswith("KEY_") and isinstance(getattr(glfw, n), int) and getattr(glfw, n) >= 0]
        return any(held(c) for c in all_keys)

    def banner():
        """Builds the operator banner for the viewer.

        Returns:
            tuple or None: None when the controller is in auto mode, or when there is neither an auto source nor an abort key. Otherwise
            (text, kind): kind "needed" with the text "OPERATOR NEEDED: <reason>" for a policy request the operator has not answered, or kind
            "control" with the text "OPERATOR CONTROL: <hand-back key> = hand back to policy, <abort key> = abort episode" (only the keys
            that are configured).
        """
        if ctl["mode"] != "teleop" or auto_src is None and not hk.get("abort"):
            return None
        if ctl["requested"] and not ctl["responded"]:
            return f"OPERATOR NEEDED: {ctl['note']}", "needed"
        keys = []
        if auto_src is not None and hk.get("hand_back") is not None:
            keys.append(f"{key_label(hk['hand_back'])} = hand back to policy")
        if hk.get("abort") is not None:
            keys.append(f"{key_label(hk['abort'])} = abort episode")
        return "OPERATOR CONTROL: " + ", ".join(keys), "control"

    # --- Bench / test hooks ---
    bench_log = None
    if cfg["bench_log"]:
        bench_log = open(cfg["bench_log"], "w", newline="")
        bench_csv = csv.writer(bench_log)
        log_joints = [model.joint(f"openarm_{sd}_joint{i}").qposadr[0] for sd in ("left", "right") for i in range(1, 8)] \
            + [model.joint(f"openarm_{sd}_finger_joint{k}").qposadr[0] for sd in ("left", "right") for k in (1, 2)]
        bench_csv.writerow(["sim_time", "base_x", "base_y", "base_yaw_deg", "pedestal_m"]
                           + [f"{sd}_joint{i}" for sd in ("left", "right") for i in range(1, 8)]
                           + [f"{sd}_finger{k}" for sd in ("left", "right") for k in (1, 2)])
    tm = {"phys": 0.0, "cam": 0.0, "inset": 0.0}
    bench_warmup = max(1, round(0.16 / tick_dt))      # ticks discarded before the benchmark timing (0.16 s: 10 ticks at 62.5 Hz)
    t_bench0 = None
    ds_state = sources["keyboard"]["state"]["drive"] if "keyboard" in sources else {}
    jog_ids = {"L3": arm_act["left"][2], "R1": arm_act["right"][0], "Lg": fing_act["left"][0], "Rg": fing_act["right"][0]}

    # --- hook API for cfg["on_tick"] ---
    stop_req = [None]
    rig_box = {"rig": rig, "gl": None}

    def render(name):
        """Renders one frame of a camera from the current state (the "render" entry of the hook API).

        Creates a camera rig on first use if the loop has none (with an offscreen context when there is no viewer); that rig is kept in
        `rig_box` and its context freed at the end of the run.

        Args:
            name (str): Camera name from robot_specs.CAMERA_SPECS.

        Returns:
            numpy.ndarray: A copy of the image, shape (height, width, 3), unsigned 8-bit red, green, blue.
        """
        if rig_box["rig"] is None:
            if viewer is not None:
                ctx = viewer["context"]
            else:
                rig_box["gl"], ctx = _headless_context(model)
            rig_box["rig"] = CameraRig(model, robot_specs.CAMERA_SPECS, ctx, shadows=cfg["camera_shadows"])
        rig_box["rig"].render(data, [name])
        return rig_box["rig"].images[name].copy()

    def snapshot_images():
        """Renders every camera at full quality from the current state (for the viewer's F3 snapshot key and test snapshots).

        Returns:
            dict: Camera name to image (numpy.ndarray of shape (height, width, 3), unsigned 8-bit), see `render`.
        """
        return {n: render(n) for n in cam_names}

    loop_api = {"routes": routes, "mode": lambda: ctl["mode"], "switch_mode": switch_mode, "stop": lambda reason="stop": stop_req.__setitem__(0, reason), "render": render}
    status = None

    def advance(vx, vy, wz, ctrl_steps):
        """Runs one tick of physics: `steps_per_frame` steps, with the ctrl and the base velocity written before each (shared by live runs and replays).

        After each step it counts the step in `step_count`, writes a row to the benchmark comma-separated values file every 75 steps if
        cfg["bench_log"] is set, calls the replay's "on_step" hook if replaying, and every `cam_every` steps renders the policy cameras
        (one camera per render with round robin, using and advancing `cam_tick`, otherwise all) and adds the time to `tm["cam"]`.

        Args:
            vx (float): World-frame base x velocity in metres per second.
            vy (float): World-frame base y velocity in metres per second.
            wz (float): Base yaw rate in radians per second.
            ctrl_steps (numpy.ndarray): The ctrl vector of each physics step, shape (steps_per_frame, model.nu).
        """
        nonlocal step_count, cam_tick
        ff_off = gff.torques(data) / gff.kp          # M185: one tau_ff / kp per tick from the measured pose (the real controller's gravity torque), held for the tick's steps
        for k in range(steps_per_frame):
            data.ctrl[:] = ctrl_steps[k]
            gff.apply_offsets(data.ctrl, ff_off)
            if base_dof is not None:
                apply_base_velocity(data, base_dof, vx, vy, wz)
            mujoco.mj_step(model, data)
            step_count += 1
            if bench_log is not None and step_count % 75 == 0:
                bench_csv.writerow([f"{data.time:.6f}", f"{data.qpos[0]:.9f}", f"{data.qpos[1]:.9f}",
                                    f"{math.degrees(base_yaw(data)):.9f}",
                                    f"{data.qpos[ped_qadr]:.9f}"] + [f"{data.qpos[a]:.9f}" for a in log_joints])
            if replay is not None:
                replay["on_step"](step_count, data)
            if rig is not None and step_count % cam_every == 0:
                t_c0 = pc()
                if cfg["camera_roundrobin"]:
                    rig.render(data, [cam_names[cam_tick % len(cam_names)]])
                    cam_tick += 1
                else:
                    rig.render(data)
                tm["cam"] += pc() - t_c0

    print(f"--- entering loop ---")
    logging_active = False
    prev_l = False
    prev_t = False
    step_count = 0
    frame = 0
    base_vx = base_vy = base_wz = 0.0
    t_f0 = pc()
    prev_take = prev_back = prev_abort = False
    if cfg["mode"] == "auto":
        switch_mode("auto", "initial")
        ctl["ramp"] = False                                # nothing is moving at the start

    # ---------------------------------------------------------------
    while True:
      try:
        if replay is not None:                           # inputs from a recording: the same physics step, no sources, no hooks
            if frame >= replay["n_ticks"] or replay["stop"]():
                break
            blk = np.asarray(replay["ctrl"][frame])
            if replay.get("gripforce") is not None:
                set_grip_force(replay["gripforce"][frame])
            advance(*replay["basevel"][frame], np.broadcast_to(blk, (steps_per_frame, model.nu)) if blk.ndim == 1 else blk)
            replay["on_tick_end"](frame, data)
            frame += 1
            continue
        t_f0 = pc()
        obs = observation(model, data)
        t = data.time
        obs.update(tick=frame, timestep=model.opt.timestep, steps_per_frame=steps_per_frame,
                   base_pose=(float(data.qpos[0]), float(data.qpos[1]), base_yaw(data)),
                   pedestal_height=float(data.qpos[ped_qadr]), applied=applied(),
                   cameras=rig.images if rig else None, render=render, mode=ctl["mode"],
                   operator={"requested": ctl["requested"], "responded": ctl["responded"]})
        if auto_src is not None and "status" in sources[auto_src]:
            obs["policy"] = sources[auto_src]["status"]()
        if cfg["on_tick"] is not None:
            status = cfg["on_tick"](obs, loop_api)
            if stop_req[0] is not None:
                break

        # F2: move the arm joints between the keyboard and the teleop source (the old set_teleop)
        if teleop is not None and hk.get("toggle_route") is not None:
            cur_t_key = held(hk["toggle_route"])
            if cur_t_key and not prev_t:
                new = "keyboard" if routes["arms.left"] == "teleop" else "teleop"
                routes["arms.left"] = routes["arms.right"] = new
                teleop["enable"]() if new == "teleop" else teleop["disable"]()
            prev_t = cur_t_key

        # Operator keys. F9 takes over from the auto source; Enter hands control back (resume()); abort ends the episode. Enter and abort act
        # only while the operator has control. Any key at all counts as a response to a policy request.
        if ctl["mode"] == "teleop" and ctl["requested"] and not ctl["responded"] and any_key_down():
            ctl["responded"] = True
        if auto_src is not None and hk.get("take_over") is not None:
            cur = key_down(hk["take_over"])
            if cur and not prev_take and ctl["mode"] == "auto":
                switch_mode("teleop", "operator_key")
            prev_take = cur
        if auto_src is not None and hk.get("hand_back") is not None:
            cur = key_down(hk["hand_back"])
            if cur and not prev_back and ctl["mode"] == "teleop":
                switch_mode("auto", "operator_key")
                if "resume" in sources[auto_src]:
                    sources[auto_src]["resume"]()
            prev_back = cur
        if hk.get("abort") is not None:
            cur = key_down(hk["abort"])
            if cur and not prev_abort and ctl["mode"] == "teleop":
                print(f"[mode] t={data.time:.2f} s (tick {frame}): the operator aborted the episode")
                stop_req[0] = "aborted_by_operator"
                break
            prev_abort = cur

        # --- Commands: every source steps; each keeps what the router gives it ---
        cmds = []
        request = None
        for name, src in sources.items():
            if name == auto_src and ctl["mode"] == "teleop":
                continue                                    # the auto source is paused while the operator is in charge
            out = src["step"](obs)
            if out is None:
                continue
            for cmd in ([out] if isinstance(out, dict) else out):
                if isinstance(cmd, dict) and cmd.get("mode") == "request_teleop":
                    clean, _ = validate_command(cmd, limits)
                    if name == auto_src and ctl["mode"] == "auto":
                        request = clean["reason"] or "operator control requested"
                    elif ("request", name) not in msgs_seen:
                        msgs_seen.add(("request", name))
                        print(f"[{name}] request_teleop ignored (only the auto source can ask, and only in auto mode)")
                    continue
                if isinstance(cmd, dict) and cmd.get("mode") in ("base", "pedestal", "arms", "idle"):
                    cmd = _filter_by_route(cmd, name, routes)       # a malformed command goes on to validate_command
                if cmd is None:
                    continue
                cmd = bridge_precheck(cmd, frame)
                if cmd is None:
                    continue
                clean, notes = validate_command(cmd, limits)
                for n in notes:
                    if (name, n) not in msgs_seen:
                        msgs_seen.add((name, n))
                        print(f"[{name}] {n}")
                if clean is not None:
                    clean["period_steps"] = command_steps(src)
                    cmds.append(clean)
        if request is not None:
            cmds = []
            switch_mode("teleop", "policy_request", request)
        if ctl["ramp"]:                                     # after a switch: the base comes to rest first
            cmds = [c for c in cmds if c["mode"] != "base"]
            stop_base()
            if st["twist"] == (0.0, 0.0):
                ctl["ramp"] = False
        measure_still()
        to_apply = exclusive_select(cmds, t) if cfg["exclusive"] else [c for c in cmds if c["mode"] != "idle"]
        if not cfg["exclusive"] and any(c["mode"] == "idle" for c in cmds):
            stop_base()
        for cmd in to_apply:
            cmd = bridge_take(cmd)
            if cmd is not None:
                apply_cmd(cmd)
        bridge_update(frame)

        # Project forward velocity into world frame using robot yaw
        base_vx, base_vy, base_wz = twist_to_world_velocity(base_yaw(data), *st["twist"])

        # --- Step physics with velocity drive ---
        t_p0 = pc()
        # The position targets are written as ctrl before every physics step (ramped between commands in "interpolate" mode); the MuJoCo
        # servos track them from the live state on every physics step.
        block = ctrl_block()
        set_grip_force([grip_force[s] for s in sides])
        if recorder is not None:
            recorder.tick(frame, block, (base_vx, base_vy, base_wz), [grip_force[s] for s in sides])
            recorder.label(frame, status.split("  (")[0] if isinstance(status, str) else status)
        advance(base_vx, base_vy, base_wz, block)
        if recorder is not None:
            recorder.end_tick(frame, data)
        tm["phys"] += pc() - t_p0

        # Logging
        if logging_active:
            logger.record(obs)
        if hk.get("toggle_log") is not None and logger is not None:
            cur_l = held(hk["toggle_log"])
            if cur_l and not prev_l:
                logging_active = not logging_active
                print(f"Logging: {'ON' if logging_active else 'OFF'}")
            prev_l = cur_l

        quit_now = False
        if viewer is not None:
            draw = frame % draw_every == 0
            if draw and irig is not None:
                if (frame // draw_every) % inset_every == 0:
                    t_c0 = pc()
                    irig.render(data, [cam_names[inset_tick % len(cam_names)]])
                    inset_tick += 1
                    tm["inset"] += pc() - t_c0
            res = viewer["frame"]({
                "draw": draw, "draw_every": draw_every, "tick_dt": tick_dt, "snapshot_images": snapshot_images,
                "frame": frame, "time": t, "t_frame_start": t_f0,
                "images": irig.images if irig is not None else (rig.images if rig else {}),
                "base_vel": (base_vx, base_vy, base_wz), "drive_state": ds_state, "targets": hold_qpos_targets,
                "teleop_status": teleop["status"]() if teleop is not None else None,
                "preview_frame": teleop["state"].get("preview_frame") if teleop is not None else None,
                "preview": cfg["preview"], "status": status, "mode": ctl["mode"] if auto_src is not None else None, "mode_note": ctl["note"],
                "banner": banner(), "alert_seq": ctl["alert_seq"]})
            quit_now = res["quit"]
            yaw_deg = res["yaw_deg"]
        else:
            yaw_deg = math.degrees(base_yaw(data))

        frame += 1
        if tick_ref is not None:
            tick_ref[0] = frame
        if cfg["bench_frames"]:
            if frame == bench_warmup:  # discard warm-up
                tm = dict.fromkeys(tm, 0.0)
                t_bench0 = pc()
            elif frame >= bench_warmup + cfg["bench_frames"]:
                n = cfg["bench_frames"]
                wall = pc() - t_bench0
                extra = " ".join(f"{k}={1000 * v / n:.0f}ms" for k, v in (viewer["timers"] if viewer else {}).items())
                print(f"BENCH {n} frames: {1000 * wall / n:.0f} ms/frame "
                      f"({n / wall:.1f} fps) | " + " ".join(f"{k}={1000 * v / n:.0f}ms" for k, v in tm.items()) + " " + extra)
                break
        # --- DEBUG ---
        verbose = (frame <= 10) or (frame % 60 == 0)
        if verbose:
            print(f"  f={frame:5d}  t={t:.2f}  "
                  f"lin={ds_state.get('linear',0):+.2f} ang={ds_state.get('angular',0):+.2f}  "
                  f"vel=[{base_vx:+.2f},{base_vy:+.2f}]  wz={base_wz:+.2f}  "
                  f"yaw={yaw_deg:+.1f}°  "
                  f"jog[L3={hold_qpos_targets[jog_ids['L3']]:+.2f} "
                  f"R1={hold_qpos_targets[jog_ids['R1']]:+.2f} "
                  f"Lg={hold_qpos_targets[jog_ids['Lg']]:.3f} "
                  f"Rg={hold_qpos_targets[jog_ids['Rg']]:.3f}]  "
                  f"pos={data.qpos[0:3].round(3)}")

        if hk.get("quit") is not None and held(hk["quit"]):
            print("ESC pressed")
            break
        if quit_now:                                     # the window was closed
            break

      except Exception as e:
            print(f"EXCEPTION in loop at frame {frame}: {e}")
            import traceback; traceback.print_exc()
            break

    # ---------------------------------------------------------------
    if viewer is not None:
        viewer["finish"]()
    if bench_log is not None:
        bench_log.close()
    if recorder is not None:
        recorder.close({"stopped_by": stop_req[0], "frames": frame})
    print(f"\nLoop exited after {frame} frames.")
    if logging_active and logger is not None and len(logger.trajectory) > 0:
        logger.save()
    for src in sources.values():
        if "cleanup" in src and src.get("started", True):
            try:
                src["cleanup"]()
            except Exception as e:                       # a source that never started has nothing to clean up
                print(f"cleanup of source '{src.get('name')}' failed: {e}")
    if viewer is not None:
        viewer["close"]()
    for gl_ctx in (gl_keepalive, rig_box["gl"]):
        if gl_ctx is not None:
            try:
                gl_ctx.free()                            # avoids an EGL error message at interpreter exit
            except Exception:
                pass
    print("Done.")
    if bridge["on"]:
        kinds = {}
        for e in bridge["log"]:
            kinds[e["kind"]] = kinds.get(e["kind"], 0) + 1
        print(f"[bridge] {len(bridge['log'])} events: {kinds}")
    return {"frames": frame, "hold_log": ex["log"], "routes": routes, "stopped_by": stop_req[0], "mode_log": ctl["log"], "bridge_log": bridge["log"]}
